"""This module contains the generation of the collector configuration for uplane traces
on an VRAN testline.
"""

# pylint: disable=E1101,W1203


import logging
from taf.ul.log_collection.config.builders.util import split_and_remove_blank_spaces

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CloudGnbUplaneTraceCollectorConfigurator:
    """concrete collector configuration builder for uplane traces on vran testlines
    """

    def add_uplane_trace(self, ne_log_name, ne_log_configuration):
        """
        Creates all uplane trace specific collectors. Dependent on the component the collection
        is executed on VDU or CU

        :param str ne_log_name: The name of the collector given in configuration
        :param dict ne_log_configuration: The trace type specific configuration dictionary
        """
        collector_names = []

        components_list = split_and_remove_blank_spaces(ne_log_configuration['components'])
        normalized_components_list = self.normalise_components(components_list)

        selected_vdu_components = list({'L2Ps', 'L2Lo', 'L2HiRlc'} & set(normalized_components_list))

        if selected_vdu_components:
            collector_names += self.create_vdu_uplane_trace_collector_configuration(
                ne_log_name,
                selected_vdu_components)

        if 'l2hiPdcp' in normalized_components_list:
            cu_collector_name = self.create_cu_uplane_trace_collector_configuration(ne_log_name)
            collector_names.append(cu_collector_name)

        uplane_trace_collector_config = {
            'name': f'{ne_log_name}',
            'type': 'group',
            'members': collector_names}

        self._collector_configuration_data.append(uplane_trace_collector_config)

        if 'L2Ps' in normalized_components_list:
            self._collector_configuration_data.add_mapping_entry(
                log_type='uplane_trace',
                network_element=f'{self.ne_type}_{self.ne_id}',
                collector_configuration=uplane_trace_collector_config)

    @staticmethod
    def normalise_components(components_list):
        """Normalises the given components_list to well defined names. Spaces, underscore and minus signs
        are removed and the case of the letters is adapted.

        :param list components_list: the components list, i.e. ["L2-PS", "L2-LO"]
        """

        allowed_components = {'L2Ps', 'L2Lo', 'l2hiPdcp', 'L2HiRlc'}

        def normalize(component):
            return {component.lower(): component for component in allowed_components}[component]

        normalized_components_list = []
        for component in components_list:
            try:
                normalized_components_list.append(
                    normalize(component.translate(str.maketrans('', '', "-_ ")).lower()))
            except KeyError as exc:
                raise ValueError(f"invalid component: {component!r}") from exc
        return normalized_components_list

    def create_vdu_uplane_trace_collector_configuration(
            self,
            ne_log_name,
            selected_vdu_components):
        """Creates the uplane trace collector for VDU, including the decorating collector to set the
        corresponding route.

        :param str ne_log_name: The name of the umbrella collector respondible for uplane trace collection
        :param dict ne_log_configuration: The log configuration provided by the user
        """

        destination_ip_address = '10.0.1.1'
        vdu_collector_names = []
        for vdu_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id):

            vdu_web_service = self.tl_config_information_provider.get_vdu_oam_http_connection_details(
                node_id=self.ne_id,
                vdu_id=vdu_id)
            nr_cell_dns = []
            l2_stream_configuration = []

            for target_component in selected_vdu_components:
                l2_stream_config = {
                    'trace_type': 'Component',
                    'target_component': target_component,
                    'nr_cell_dn_list': nr_cell_dns
                }
                l2_stream_configuration.append(l2_stream_config)

            tcpdump_collector = {
                'name': f'tcpdump_uplane_gnb_{self.ne_id}_vdu_{vdu_id}',
                'type': 'tcpdump',
                'options': f'-i eth9 udp and dst {destination_ip_address} and dst port 5679',
                'sudo_password': 'ute'
            }
            self._collector_configuration_data.append(tcpdump_collector)

            l2stream_vdu_collector = {
                'name': f'{ne_log_name}_vdu_{vdu_id}',
                'webservice': vdu_web_service,
                'destination_ip_addr': destination_ip_address,
                'destination_port_number': 5679,
                'collector': tcpdump_collector['name'],
                'type': 'l2stream3_vdu',
                'l2_stream_configuration': l2_stream_configuration
            }

            decorating_l2stream_vdu_collector = {
                'name': f'{ne_log_name}_vdu_{vdu_id}_decorating',
                'type': 'log_collection_cloud_gnb_uplane_trace',
                'static_route': {'dest_ip_addr': '10.0.1.1',
                                 'gateway': '172.16.2.10',
                                 'admin': vdu_web_service},
                'cloud_part': 'vdu',
                'collector': l2stream_vdu_collector['name']
            }
            self._collector_configuration_data.append(decorating_l2stream_vdu_collector)
            self._collector_configuration_data.append(l2stream_vdu_collector)

            vdu_collector_names.append(decorating_l2stream_vdu_collector['name'])
        return vdu_collector_names

    def create_cu_uplane_trace_collector_configuration(self, ne_log_name):
        """
        From:
        https://taf-collectors-l2stream3.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html#taf.collectors.l2stream3.interface.l2stream3.create_cu_l2stream_collector
        Allowed target_component: l2hiPdcp
        """
        destination_ip_addr = '10.0.1.1'

        cu_web_service = self.tl_config_information_provider.get_cu_oam_http_connection_details(node_id=self.ne_id)

        l2_stream_config = {
            'trace_type': 'Component',
            'target_component': 'l2hiPdcp'}

        l2_stream_configuration = [l2_stream_config]
        tcpdump_collector = {
            'name': f'tcpdump_uplane_gnb_{self.ne_id}_cu',
            'type': 'tcpdump',
            'options': f'-i eth9 udp and dst {destination_ip_addr} and dst port 5678',
            'sudo_password': 'ute'}

        self._collector_configuration_data.append(tcpdump_collector)

        l2stream_cu_collector = {
            'name': f'{ne_log_name}_gnb_cu_{self.ne_id}',
            'webservice': cu_web_service,
            'destination_ip_addr': destination_ip_addr,
            'collector': tcpdump_collector['name'],
            'type': 'l2stream3_cu',
            'l2_stream_configuration': l2_stream_configuration,
            'timeout': 50}

        decorating_l2stream_cu_collector = {
            'name': f'{ne_log_name}_gnb_cu_{self.ne_id}_decorating',
            'type': 'log_collection_cloud_gnb_uplane_trace',
            'static_route': {
                'dest_ip_addr': '10.0.1.1',
                'gateway': '172.16.2.10',
                'admin': cu_web_service},
            'cloud_part': 'cu',
            'collector': l2stream_cu_collector['name']
        }

        self._collector_configuration_data.append(l2stream_cu_collector)
        self._collector_configuration_data.append(decorating_l2stream_cu_collector)
        return decorating_l2stream_cu_collector['name']
